<?php require __DIR__.'/bootstrap.php';require __DIR__.'/layout.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$id=(int)($_POST['product_id']??0);$action=$_POST['action']??'';if($action==='clear'){$_SESSION['cart']=[];}elseif($action==='remove'){unset($_SESSION['cart'][$id]);}elseif($action==='add'||$action==='update'){ $s=db()->prepare('SELECT stock FROM products WHERE id=? AND is_active=1');$s->execute([$id]);$stock=$s->fetchColumn();if($stock===false)throw new InvalidArgumentException('Product unavailable');$qty=$action==='update'?filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT):(int)($_SESSION['cart'][$id]??0)+1;if($qty===false||$qty<1||$qty>9999)throw new InvalidArgumentException('Enter a quantity from 1 to 9999');if($qty>(int)$stock)throw new InvalidArgumentException('Not enough stock');$_SESSION['cart'][$id]=$qty;}else{throw new InvalidArgumentException('Invalid cart action');}unset($_SESSION['checkout_token']);redirect('cart.php');}catch(Throwable $e){$error=request_error($e,'cart.php failed');}}$cart=$_SESSION['cart']??[];$items=[];$total=0;if($cart){$ids=array_keys($cart);$place=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT * FROM products WHERE is_active=1 AND id IN ($place)");$s->execute($ids);$items=$s->fetchAll();$available=array_column($items,'id');foreach(array_keys($cart) as $id){if(!in_array($id,$available)){unset($_SESSION['cart'][$id],$cart[$id]);unset($_SESSION['checkout_token']);}}foreach($items as $i)$total+=(float)$i['price']*$cart[$i['id']];}head_html('Cart');?><h1>Your cart</h1><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif;?><?php if(!$items):?><p>Cart is empty. <a class="accent" href="index.php">Browse parts →</a></p><?php else:?><div class="panel"><table class="table"><tr><th>Item</th><th>Qty</th><th>Subtotal</th><th></th></tr><?php foreach($items as $i):?><tr><td><?=e($i['name'])?></td><td><form method="post" class="flex"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="product_id" value="<?=(int)$i['id']?>"><input type="number" name="quantity" min="1" max="9999" value="<?=(int)$cart[$i['id']]?>" style="width:85px"><button class="btn alt" name="action" value="update">Update</button></form></td><td>₱<?=number_format($i['price']*$cart[$i['id']],2)?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="product_id" value="<?=$i['id']?>"><button class="btn alt" name="action" value="remove">Remove</button></form></td></tr><?php endforeach;?></table><h2>Total: ₱<?=number_format($total,2)?></h2><a class="btn" href="checkout.php">Checkout →</a></div><?php endif;foot_html();